import json,glob,importlib,sys
sys.path.insert(0,'programs')
bad=[]
for pj in glob.glob('programs/task-*.json'):
    tid=pj.split('/')[-1][:-5]
    try:
        mod=importlib.import_module(tid); importlib.reload(mod)
    except Exception as e:
        bad.append((tid,'import',str(e))); continue
    for p in json.load(open(pj)):
        try:
            if mod.transform(p['input'])!=p['output']: bad.append((tid,'mismatch',''))
        except Exception as e: bad.append((tid,'run',str(e)))
print('bad:',bad)
print(json.load(open('programs/task-faa76b7b.json')).__len__(),'pairs kept')
